sys_variable_value.value:
(function execute(inputs, outputs) {
	try {
		var finputs = {};
		finputs['current'] = inputs.p1 // GlideRecord of table:  
		finputs['table_name'] = 'x_1770592_easy_t_0_my_asset_request';

		// Start Asynchronously: Uncomment to run in background.
		// sn_fd.FlowAPI.getRunner().flow('x_1770592_easy_t_0.demo33').inBackground().withInputs(inputs).run();
				
		// Execute Synchronously: Run in foreground.
		sn_fd.FlowAPI.getRunner().flow('x_1770592_easy_t_0.demo33').inForeground().withInputs(finputs).run();
		
	} catch (ex) {
		var message = ex.getMessage();
		gs.error(message);
	}
})(inputs, outputs);

